CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, glossary TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chunks(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, generation INTEGER NOT NULL, content TEXT NOT NULL, metadata TEXT NOT NULL, vector TEXT);
CREATE VIRTUAL TABLE IF NOT EXISTS chunks_fts USING fts5(id UNINDEXED, project_id UNINDEXED, content, tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER IF NOT EXISTS chunk_insert AFTER INSERT ON chunks BEGIN INSERT INTO chunks_fts(id,project_id,content) VALUES(new.id,new.project_id,new.content); END;
CREATE TRIGGER IF NOT EXISTS chunk_delete AFTER DELETE ON chunks BEGIN DELETE FROM chunks_fts WHERE id=old.id; END;
CREATE TABLE IF NOT EXISTS indexing_jobs(id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meetings(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS caption_segments(id TEXT NOT NULL, meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, epoch TEXT NOT NULL, revision INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(meeting_id,id));
CREATE TABLE IF NOT EXISTS applied_events(meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,event_id TEXT NOT NULL,epoch TEXT NOT NULL,seq INTEGER NOT NULL,ack TEXT NOT NULL,PRIMARY KEY(meeting_id,event_id));
CREATE TABLE IF NOT EXISTS capture_gaps(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_requests(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suggestions(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,request_id TEXT NOT NULL REFERENCES ai_requests(id) ON DELETE CASCADE,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,version INTEGER NOT NULL,payload TEXT NOT NULL,UNIQUE(meeting_id,version));
CREATE TABLE IF NOT EXISTS controls(meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,key TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(meeting_id,key));
CREATE INDEX IF NOT EXISTS meeting_project ON meetings(project_id);
CREATE INDEX IF NOT EXISTS chunk_scope ON chunks(project_id,source_id,generation);
